func multiplyMatrices(matrixA [][]int, matrixB [][]int) [][]int {
    if len(matrixA[0]) != len(matrixB) {
        return nil
    }
    result := make([][]int, len(matrixA))
    for i := range result {
        result[i] = make([]int, len(matrixB[0]))
    }
    for i := range matrixA {
        for j := range matrixB[0] {
            sum := 0
            for k := range matrixA[0] {
                sum += matrixA[i][k] * matrixB[k][j]
            }
            result[i][j] = sum
        }
    }
    return result
}

