func multiplyMatrices(a, b [][]int) [][]int {
	result := make([][]int, len(a))
	for i, row := range a {
		result[i] = make([]int, len(b[0]))
		for j, val := range row {
			result[i][j] = a[i][j] * b[i][j]
		}
	}
	return result
}

